import { useId } from 'react'

type LogoMarkProps = { size?: number; className?: string; animated?: boolean }

/**
 * The Quizz mark.
 *
 * A magnifier reads as "search your answers"; its lens doubles as the bowl of a
 * Q, the tail doubles as the handle, and the tick inside is the answer found.
 * Geometry lives on a 48-unit grid so the SVG, the launcher icon (generated by
 * tools/make_assets.py) and the splash stay identical.
 */
export function LogoMark({ size = 38, className = '', animated = false }: LogoMarkProps) {
  const uid = useId().replace(/:/g, '')
  const glyph = `q-glyph-${uid}`
  const check = `q-check-${uid}`
  const spark = `q-spark-${uid}`

  return (
    <span
      className={`logo-mark ${className}`}
      style={{ width: size, height: size, borderRadius: Math.round(size * 0.3) }}
    >
      <svg viewBox="0 0 48 48" fill="none" aria-hidden="true" style={{ width: size * 0.82, height: size * 0.82 }}>
        <defs>
          <linearGradient id={glyph} x1="8" y1="6" x2="40" y2="42" gradientUnits="userSpaceOnUse">
            <stop offset="0" stopColor="#FFFFFF" />
            <stop offset="0.62" stopColor="#EEF2FF" />
            <stop offset="1" stopColor="#CFE0FF" />
          </linearGradient>
          <linearGradient id={check} x1="15" y1="27" x2="28" y2="18" gradientUnits="userSpaceOnUse">
            <stop offset="0" stopColor="#7DF9FF" />
            <stop offset="1" stopColor="#22D3EE" />
          </linearGradient>
          <linearGradient id={spark} x1="35" y1="6" x2="44" y2="15" gradientUnits="userSpaceOnUse">
            <stop offset="0" stopColor="#FFFFFF" />
            <stop offset="1" stopColor="#7DF9FF" />
          </linearGradient>
        </defs>

        {/* lens body = the Q bowl */}
        <circle cx="21.6" cy="23.4" r="11.6" stroke={`url(#${glyph})`} strokeWidth="4" />
        {/* handle = the Q tail, tucked under the bowl */}
        <path d="M28.7 30.5 L35.6 37.6" stroke={`url(#${glyph})`} strokeWidth="4.4" strokeLinecap="round" />
        {/* the answer */}
        <path
          d="M15.4 23.3 L19.3 27.2 L27 18.7"
          stroke={`url(#${check})`}
          strokeWidth="3.8"
          strokeLinecap="round"
          strokeLinejoin="round"
          className={animated ? 'logo-draw' : undefined}
          style={animated ? { strokeDasharray: 24, strokeDashoffset: 24 } : undefined}
        />
        {/* spark = the "new idea" tick of AI-generated tests */}
        <path
          d="M39 5.8 C39 8.6 41.2 10.4 43.6 10.4 C41.2 10.4 39 12.2 39 15 C39 12.2 36.8 10.4 34.4 10.4 C36.8 10.4 39 8.6 39 5.8 Z"
          fill={`url(#${spark})`}
        />
      </svg>
    </span>
  )
}

export function Wordmark({ size = 22 }: { size?: number }) {
  return (
    <span className="logo-word" style={{ fontSize: size }}>
      Quiz<em>z</em>
    </span>
  )
}

export function Logo({ size = 38 }: { size?: number }) {
  return (
    <span className="logo">
      <LogoMark size={size} />
      <Wordmark size={size * 0.58} />
    </span>
  )
}
